local _, ns = ...
if ns.LOCALE ~= "deDE" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/deDE.lua.
L["WN53_1_TITLE"] = "Feinere Designteile"
L["WN53_1_TEXT"] = "Unter Eigenes Design ist die Liste Mit Thema in feinere Teile aufgeteilt, etwa Zauberleisten, Namensplaketten, das Mikromenü und Menüs, damit du jedes davon im klassischen Look lassen kannst. Eigenes Design ist standardmäßig aus; schalte es in den Optionen (/fcui) unter Aussehen ein."
L["WN53_2_TITLE"] = "Rechte Aktionsleisten"
L["WN53_2_TEXT"] = "Mit ausgeschalteter Klassischer Leiste und einer im Bearbeitungsmodus vergrößerten Minikarte schrumpfen die Aktionsleisten 4 und 5 rechts nicht mehr auf etwa zwei Drittel; sie werden nur so weit kleiner, wie der Platz unter der Minikarte es verlangt."
L["WN53_3_TITLE"] = "Eigene Farbe"
L["WN53_3_TEXT"] = "Ein Klick außerhalb der Farbauswahl behält die gewählte Farbe; Abbrechen oder Escape macht sie weiterhin rückgängig."
L["WN53_4_TITLE"] = "Design-Korrekturen"
L["WN53_4_TEXT"] = "Färbt das Design die Fenster des Spiels, blitzen sie beim Öffnen nicht mehr in ihren eigenen Farben auf, und die roten Knöpfe des Spielmenüs zeigen ihre Enden richtig. Fenster anderer Addons behalten ihren eigenen Look; um sie mitzufärben, schalte Andere Addons in der Liste Mit Thema ein, in den Optionen (/fcui) unter Aussehen."
L["WN52_1_TITLE"] = "Ehrenabzeichen"
L["WN52_1_TEXT"] = "Spieler-, Ziel- und Fokusfenster können das Ehrenstufen-Abzeichen des Spiels anstelle des 1.x-Fraktionswappens zeigen. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Einheitenfenster ein."
L["WN52_2_TITLE"] = "Chat-Reiter beim Überfahren"
L["WN52_2_TEXT"] = "Mit Chat-Reitern beim Überfahren erscheinen nur die Reiter des Chatfensters unter der Maus: die angedockten Fenster gemeinsam, ein herausgezogenes Fenster für sich."
L["WN52_3_TITLE"] = "Gruppensuche-Auge"
L["WN52_3_TEXT"] = "An Minikarte ausrichten für das Gruppensuche-Auge ist nicht mehr in den Optionen; es bleibt in den Einstellungen des Auges im Bearbeitungsmodus."
L["WN52_4_TITLE"] = "Gruppensuche-Auge"
L["WN52_4_TEXT"] = "An Minikarte ausrichten für das Gruppensuche-Auge ist aus den Optionen in sein Feld Gruppensuche in ClassicUI Forever Fenster (Bearbeitungsmodus) gewandert, unter Minikarte. Das Feld bleibt, solange das Auge nicht am Rand steht, damit du es wieder einschalten kannst."
L["WN52_5_TITLE"] = "Tooltip von Schadensblitz"
L["WN52_5_TEXT"] = "Der Tooltip von Schadensblitz sagt, dass das Rot auf der Gesundheitsleiste des Spielerfensters erscheint. Schadensblitz ist standardmäßig aus; schalte es in den Optionen (/fcui) unter Einheitenfenster ein."
L["WN51_1_TITLE"] = "Meisterschaft und Vielseitigkeit"
L["WN51_1_TEXT"] = "Die Werte im Charakterfenster zeigen Meisterschaft und Vielseitigkeit unter Allgemein."
L["WN51_2_TITLE"] = "Berufsfenster"
L["WN51_2_TEXT"] = "Die Wahl der Erweiterung steht jetzt im Filtermenü. Das Fenster öffnet sich dort, wo die anderen Fenster des Spiels stehen, ohne Lücke nach dem Zauberbuch, und sein unterer Rand verläuft unter den Herstellen-Knöpfen."
L["WN51_3_TITLE"] = "Optionen von Eine Tasche"
L["WN51_3_TEXT"] = "Die Optionen unter Eine Tasche ändern nur die Taschenfenster des Addons und sind daher ausgegraut, solange Taschenfenster aus ist. Um sie zu nutzen, schalte es in den Optionen (/fcui) unter Taschen ein."
L["WN51_4_TITLE"] = "Reiter"
L["WN51_4_TEXT"] = "Im Berufs- und im Talentfenster zeigt der gewählte Reiter seine ganze Fläche, und die anderen Reiter zeigen kein schwarzes Band mehr."
L["WN50_1_TITLE"] = "Mit Textur"
L["WN50_1_TEXT"] = "Mit Textur, das die Textur der Grafik in der Farbe des Themas behält, färbt jetzt ganze Fenster, nicht nur ihr Metall: den Stein von Taschen und Reitern, die Ränder von Such- und Eingabefeldern und die Seitenpfeile des Zauberbuchs, wobei ein nutzbarer Pfeil heller ist als ein verbrauchter. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Aussehen ein."
L["WN50_2_TITLE"] = "Themen auf den Fenstern des Spiels"
L["WN50_2_TEXT"] = "Themen färben auch die eigene Grafik des Spiels, die in den vom Addon umgestalteten Fenstern bleibt: die Reiter des Kontaktfensters, Bildlaufleisten, Suchfelder, Auswahllisten wie die Statuswahl, das Geldfeld, die Spaltenköpfe der Gildenliste, das Chatfeld der Communitys und den Schlachtzugreiter."
L["WN50_3_TITLE"] = "Bronze auf Retail"
L["WN50_3_TEXT"] = "Das Bronze-Thema färbt jetzt auch die eigene Fenstergrafik des Spiels, die auf Retail silbern ist, wie es die anderen Themen tun."
L["WN50_4_TITLE"] = "Hilfeknöpfe ausblenden"
L["WN50_4_TEXT"] = "Blendet die Hilfeknöpfe des Spiels aus, das i oben links an Fenstern wie Karte, Berufen und Zauberbuch, und die Tutorialtipps, die sie öffnen. Standardmäßig an; schalte es in den Optionen (/fcui) unter Sonstiges aus."
L["WN50_5_TITLE"] = "Wer-Seitenreiter ausblenden"
L["WN50_5_TEXT"] = "Die Gruppensuche kann ihren Wer-Seitenreiter weglassen, sodass Wer nur über das Kontaktfenster erreichbar ist. An für neue Installationen; wenn du das Addon schon genutzt hast, schalte es in den Optionen (/fcui) unter Kontakte ein."
L["WN50_6_TITLE"] = "Fehlerbehebungen"
L["WN50_6_TEXT"] = "Der Porträtring des Zauberbuchs nimmt das Bronze-Thema an, statt silbern zu bleiben, und ein Seitenpfeil, der wieder blättern kann, behält nicht mehr seine verbrauchte Farbe, bis du woanders klickst. Namensplaketten zeigen den Totenkopf für freundliche Einheiten unbekannter Stufe, wie der Zielrahmen. Der innere Rand auf den Reitern Freunde und Schlachtzug des Kontaktfensters die Farbe des Themas an, und ein Fehler, den das Thema im Kampf auslösen konnte, ist behoben."
L["WN49_1_TITLE"] = "Kleiner und leichter"
L["WN49_1_TEXT"] = "Der Download ist weniger als halb so groß wie bisher, und das Addon braucht weniger Speicher. Themen färben jetzt die Grafik des Spiels selbst, statt Kopien davon mitzuliefern, und ein Teil im Thema entsteht erst, wenn es zum ersten Mal erscheint. Die Themen sehen aus wie bisher."
L["WN49_2_TITLE"] = "Zonentext ausblenden"
L["WN49_2_TEXT"] = "Blendet die Zonen- und Unterzonennamen aus, die beim Betreten eines Gebiets auf dem Bildschirm eingeblendet werden. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Sonstiges ein."
L["WN49_3_TITLE"] = "Zauberbuch und Leisten"
L["WN49_3_TEXT"] = "Solange das Zauberbuch offen ist, zeigen die seitlichen Leisten wie in Era ihre leeren Plätze, sodass sich ein Zauber direkt auf einen davon legen lässt, auch im Kampf."
L["WN49_4_TITLE"] = "Reiter des Charakterfensters"
L["WN49_4_TEXT"] = "Die Reiter des Charakterfensters sind die von Era, wie auf Forever: so breit wie ihre Namen, und der gewählte Reiter geht offen in die Seite über."
L["WN49_5_TITLE"] = "Optionsseiten"
L["WN49_5_TEXT"] = "Die Seiten des Optionsfensters sind nach Art gruppiert: zuerst Aussehen, dann die Teile auf dem Bildschirm, die Seiten Minikarte und Karte nebeneinander, dann die Fenster des Spiels und zuletzt Sonstiges."
L["WN49_6_TITLE"] = "Fehlerbehebungen"
L["WN49_6_TEXT"] = "Die Statistik- und Ausrüstungslisten des Charakterfensters zeigen wieder ihre Bildlaufpfeile. Das Porträt des Zauberbuchs füllt wie in Era seinen Ring, das des Berufebuchs passt dazu und wächst beim Öffnen nicht mehr, und das Symbol des Sammlungsfensters ist nicht mehr zu nah herangezoomt. Das Mausrad zoomt die Vorschau unter Vorlagen, und die eingeklappte Schlachtzugsverwaltung zeigt keine überflüssige Linie mehr."
L["WN48_1_TITLE"] = "Karte und Questlog vereint"
L["WN48_1_TEXT"] = "Die Questliste neben der Karte, Text und Belohnungen der gewählten Quest auf zwei Seiten darunter, wie die Karte aus Wrath. Zieh die Ecke der Karte für die Größe und den Trenner für eine breitere Liste. Standardmäßig aus; schalte Klassische Karte und Quests vereint in den Optionen (/fcui) unter Karte ein, mit der Navigationsleiste: Classic-Stil."
L["WN48_2_TITLE"] = "Text der Questliste"
L["WN48_2_TEXT"] = "Schriftgröße der Questliste und Schriftgröße des Questtexts machen Questlisten und Questtext der Karte größer, und Liste auf dem Pergament des Spiels legt die Liste auf die Questlog-Seite des Spiels statt auf dunklen Stein. Sie beginnen beim Aussehen des Spiels; schalte sie in den Optionen (/fcui) unter Karte ein."
L["WN48_3_TITLE"] = "Gilde wie in Era"
L["WN48_3_TEXT"] = "Der Gildenreiter folgt dem Layout von Classic Era: Spaltenköpfe, die Leiste über der Nachricht des Tages, die Zähler, die Knöpfe und das Feld Offline-Mitglieder anzeigen stehen, wo Era sie hat, und Klassennamen sind weiß."
L["WN48_4_TITLE"] = "Bank wie in Era"
L["WN48_4_TEXT"] = "Die Bank behält das größere Raster von Forever und darunter das Layout von Era: eine Reihe Taschenplätze in voller Größe, die Kaufzeile und dein Geld auf einem Streifen am unteren Rand."
L["WN48_5_TITLE"] = "Gebiet bei Zonennamen"
L["WN48_5_TEXT"] = "Das Gebiet einer Zone, etwa Allianzgebiet, steht wie in 1.x auch außerhalb der Hauptstädte. Für die Namen des Spiels entferne das Häkchen bei Gebiet bei Zonennamen in den Optionen (/fcui) unter Sonstiges."
L["WN48_6_TITLE"] = "Plätze des klassischen Layouts"
L["WN48_6_TEXT"] = "Der Knopf Klassisches Layout und die Einrichtung beim ersten Einloggen setzen Spieler-, Ziel- und Fokusrahmen sowie die Leisten 4 und 5 dorthin, wo Classic Era sie hat. Von selbst bewegt sich nichts: drück im Optionsfenster Klassisches Layout, um sie zu nutzen."
L["WN48_7_TITLE"] = "Untere Leiste"
L["WN48_7_TEXT"] = "Der Weltkarten-Knopf steht wie in Era hinter dem Kontakte-Knopf, und die Kunst des Mikromenüs ist die von Era, zum rechten Ende hin dunkler, mit dem Latenzfenster, dem Schlüsselbund und den Taschen daneben, wo Era sie hat."
L["WN48_8_TITLE"] = "Kleinere Optionen"
L["WN48_8_TEXT"] = "Das \"Erhalten\"-Fenster des Spiels für seltene Beute, einen gewonnenen Wurf oder ein Upgrade ist ausgeblendet, da 1.x keines hatte; Beute-Hinweis bringt es zurück. Suchfeld der Taschen ausblenden und Aufräumen-Knopf ausblenden nehmen diese von den Taschen. Alle drei sind standardmäßig aus; schalte sie in den Optionen (/fcui) unter Sonstiges und Taschen ein. Die Kartenkoordinaten unter Karte sind Einstellungen des Spiels selbst."
L["WN48_9_TITLE"] = "Auf Retail"
L["WN48_9_TEXT"] = "Das Auge der Gruppensuche wandert um die Minikarte und hat eine Größe in den Minikarten-Optionen unseres Bearbeitungsmodus, kritische Treffer und Tempo zeigen die Tooltips des Spiels, und Hilfeknopf der Karte ausblenden blendet den Tutorial-Knopf der Karte aus. Standardmäßig aus; schalte ihn in den Optionen (/fcui) unter Karte ein."
L["WN48_10_TITLE"] = "Fehlerbehebungen"
L["WN48_10_TEXT"] = "Das Leuchten bei Schwächungen im Gruppenrahmen ist ein Ring um das Porträt, eine leer geplünderte Seite blättert zur nächsten, das Auge der Gruppensuche wächst mit der Minikarte und verschwindet oder meldet keinen Fehler mehr im Bearbeitungsmodus, das Spaltenmenü der Wer-Liste wählt und sortiert eine Spalte direkt, und Questseiten ergänzen spät eintreffende Belohnungen. Talente betrachten im Kampf zeigt nur unser Fenster, und ein Kampf mitten im Ziehen hält das Fenster an, wo es ist."
L["WN47_1_TITLE"] = "Gilde und Gemeinschaften"
L["WN47_1_TEXT"] = "Das Fenster Gilde und Gemeinschaften ist jetzt eine Seite des Kontaktefensters: es trägt in beiden Modi die Reiter Freunde, Wer, Gilde und Schlachtzug, und der kleine Modus hat die Größe des Kontaktefensters, mit Ring und Porträt."
L["WN47_2_TITLE"] = "Profile als Text"
L["WN47_2_TEXT"] = "Exportieren und Importieren auf der Profilseite: ein Profil als eine Textzeile zum Kopieren auf einen anderen Account oder an einen Freund, und zurück in ein neues Profil."
L["WN47_3_TITLE"] = "Menübreite"
L["WN47_3_TEXT"] = "Der Bearbeitungsdialog des Mikromenüs hat neben Größe einen Regler Menübreite: die Reihe wird breiter oder schmaler, die Knöpfe behalten ihre Größe. Größe über 100 % verbreitert jetzt die Kunst mit der Reihe."
L["WN47_4_TITLE"] = "Kontaktefenster"
L["WN47_4_TEXT"] = "Das Kontaktefenster bleibt nach einer Wer-Suche an seinem Platz, der Statusknopf unter dem Titel nimmt Klicks an, ausgeblendete Mikroknöpfe öffnen ihre Fenster nicht mehr aus einem leeren Sitz."
L["WN47_5_TITLE"] = "Karte im Kampf"
L["WN47_5_TEXT"] = "Die Weltkarte ist im Kampf nur geschützt, solange die klassische Karte dieses Addons sie anordnet, sodass Kartenaddons im Kampf funktionieren, wenn die klassische Karte aus ist."
L["WN46_1_TITLE"] = "Kontaktefenster"
L["WN46_1_TEXT"] = "Der Schlachtzug-Reiter ist zurück in der Reiterzeile des Kontaktefensters, wo das neue Kontaktesystem des Spiels aus ist, und der kleine Reiter unter Kürzlich Verbündete heißt wieder Schnellbeitritt statt Schlachtzug. Das Fenster lässt sich jetzt nur noch an seiner Titelleiste ziehen, sodass der Statusknopf unter dem Titel wieder Klicks annimmt."
L["WN45_1_TITLE"] = "Sammlungen auf Retail"
L["WN45_1_TEXT"] = "Das klassische Sammlungsfenster gibt es jetzt auch auf Retail: Reittiere, Haustiere mit deinem Kampfteam daneben, Spielzeuge und Erbstücke als Buchseiten, Lagerplätze und Vorlagen, jede Seite mit den Filtern des Spiels. Ziehe eine Vorschau, um sie zu drehen, scrolle über einer Kreatur zum Zoomen, ziehe eine Vorlage mit der rechten Maustaste, um sie zu verschieben; der Knopf neben den Pfeilen setzt sie zurück. Sammlungsfenster ist standardmäßig an, in den Optionen (/fcui) unter Charakter, Zauber, Talente."
L["WN45_2_TITLE"] = "Eine Suche auf jeder Seite"
L["WN45_2_TEXT"] = "Jede Optionsseite hat oben rechts ein eigenes Suchfeld, das nur diese Seite durchsucht; die Suche oben links deckt weiterhin alle Seiten ab. Alle aus und Standardoptionen sind nach unten rechts gewandert. Fenster im klassischen Stil ist von Alle Fenster verschwunden: Jedes Fenster ist jetzt ein eigenes Kästchen, und keine Zeile wird wegen einer anderen ausgegraut."
L["WN45_3_TITLE"] = "Statistiksuche"
L["WN45_3_TEXT"] = "Ein Suchfeld im Statistik-Reiter des Charakterfensters findet Statistiken nach Name oder Kategorie. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Charakter, Zauber, Talente ein."
L["WN45_4_TITLE"] = "Oberflächengröße"
L["WN45_4_TEXT"] = "Das klassische Layout stellt die UI-Skalierung des Spiels auf die Größe von Classic Era, auf den meisten Bildschirmen 90%. Alle aus in der Seitenleiste der Optionen bietet jetzt an, deine alte Größe zurückzusetzen, mit einem Kästchen in seiner Abfrage, und Standardoptionen bietet Eras Größe an, solange du eine andere hast. Beide Abfragen raten, vorher ein Profil zu speichern, um zu deinen Einstellungen zurückzukehren, und die FAQ-Seite erklärt die Größe."
L["WN45_5_TITLE"] = "Wer-Liste aus"
L["WN45_5_TEXT"] = "Ist die Wer-Liste aus, öffnen der Wer-Reiter im Kontaktefenster und der seitliche Wer-Reiter der Gruppensuche Forevers eigene Wer-Liste, eine Seite der Gruppensuche; Eintragen und Durchsuchen führen zurück zu den klassischen Seiten. Wer-Reiter ausblenden nimmt den Reiter unten vom Kontaktefenster. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Kontakte ein."
L["WN45_6_TITLE"] = "Taschen und Leisten"
L["WN45_6_TEXT"] = "Schlüsselbundgrafik ausblenden nimmt die Grafik des Schlüsselbunds von der Leiste. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Taschen ein. Auf Retail hat die Materialtasche eigene Auswahlen unter Taschen: als Schlüsselgrafik, als gestauchte Taschengrafik, ein voller Platz oder ausgeblendet. Eine Leiste schaltet nichts anderes mehr ein und listet ihre Paare darunter auf, und die modernen Seitenpfeile stehen mit Greifen über den Leisten über dem Greifen."
L["WN45_7_TITLE"] = "Korrekturen"
L["WN45_7_TEXT"] = "Auf Retail sah ein Mondkin-Druide zwei Manaleisten; jetzt zeigt sich nur unsere, unter der Astralkraft. Die Berufe-Seite des Zauberbuchs rückt zurück, wenn ein anderes Fenster schließt, und auf Retail öffnet sich das Handwerksfenster neben dem Zauberbuch statt darüber, mit seinem Rahmen unter der Herstellen-Zeile; sein Vergrößern-Knopf ist weg, da die Seite des Spiels vom Rezept aus erreichbar ist. Das Auge der Gruppensuche bleibt im Bearbeitungsmodus am Rand der Minikarte, und auf Retail schiebt es Umschalt-Ziehen am Rand entlang. Das Bearbeitungsmodus-Kästchen des Mikromenüs blitzt nicht mehr in der Ecke auf, der Hinweis eines Mikroknopfs pulsiert mit dem 1.x-Leuchten, freundliche Namensplaketten blitzen auf Retail nicht mehr lila, eine Sammlungsvorschau öffnet sich gerahmt, Alle aus hakt auch die Fenster unter einem Elternkästchen ab, Beutewürfe ist bei Neuinstallationen standardmäßig an, und die Optionssuche lässt die Zeilen über einem Treffer hell."
L["WN44_1_TITLE"] = "Themen in einer Farbe"
L["WN44_1_TEXT"] = "Themen zeichnen jetzt standardmäßig alles in einer gleichmäßigen Farbe, wie ein Dunkelmodus. Um Texturen für gewählte Teile zurückzuholen, schalte Mit Textur in den Optionen (/fcui) unter Aussehen ein; Mit Thema wählt, welche Teile das Thema überhaupt annehmen. Auch Pergament nimmt das Thema an, mit hellem Text auf dunkler Seite. Wer schon ein Thema nutzte, behält sein Aussehen."
L["WN44_2_TITLE"] = "Klassische Münzen"
L["WN44_2_TEXT"] = "Gold, Silber und Kupfer zeigen die runden Münzen von Era in Taschen, bei Händlern, in Post, Quests und Tooltips. Entferne den Haken bei Klassische Münzen in den Optionen (/fcui) unter Aussehen für die modernen."
L["WN44_3_TITLE"] = "Eine Leiste"
L["WN44_3_TEXT"] = "Eine Leiste blendet jetzt auch die Latenzleiste aus und stellt den Schlüsselbund zu den Taschen, über deren eigene Optionen, also kann beides zurückkommen. Moderne Seitenpfeile zeigt die kleinen Seitenpfeile des Spiels auf dem linken Greif; es ist standardmäßig aus, schalte es in den Optionen unter Eine Leiste ein."
L["WN44_4_TITLE"] = "Taschen"
L["WN44_4_TEXT"] = "Qualitätsrahmen ausblenden und Schrottmünze ausblenden nehmen deinen Gegenständen die farbigen Qualitätsrahmen und die goldene Münze beim Händler. Beide sind standardmäßig aus, schalte sie in den Optionen unter Taschen ein."
L["WN44_5_TITLE"] = "Minikarte"
L["WN44_5_TEXT"] = "Tastenrahmen ausblenden hat ein Auswahlmenü Tasten, um zu wählen, welche Tasten ihren Ring verlieren, die Minikartentaste jedes Addons kann eine eigene Wahl haben, und das Auge der Gruppensuche bleibt am Rand der Minikarte."
L["WN44_6_TITLE"] = "Behoben"
L["WN44_6_TEXT"] = "Ein angeklicktes Namensschild behält seinen gelben Namen, solange die Maus darauf ist. Eine Option blendet die Überschrift Alle Ziele der Questverfolgung aus, die Optionen haben eine Seite Alle Fenster, und die Werte der Statusauswahl folgen den Profilen."
L["WN43_1_TITLE"] = "Eckige Minikarte"
L["WN43_1_TEXT"] = "Eckige Minikarte macht die Karte eckig, im Metall des runden Rands, die Tasten am Rand folgen der Kante. Sie ist standardmäßig aus, schalte sie in den Optionen (/fcui) unter Minikarte ein. Solange Minikarte drehen im Spiel an ist, bleibt die Karte rund."
L["WN43_2_TITLE"] = "Minikarte"
L["WN43_2_TEXT"] = "Schließen-Knopf der Minikarte setzt Eras X auf die Zonenleiste: ein Klick blendet die Karte aus, ein weiterer holt sie zurück. Er ist standardmäßig aus, schalte ihn in den Optionen unter Minikarte ein. Im Bearbeitungsmodus lässt sich die Zonenleiste jetzt unter die Karte setzen, die Uhr steht an Eras Stelle in Eras Rahmen, und Umschalt zum Ziehen der Minikartentasten lässt sich für einfaches Ziehen ausschalten."
L["WN43_3_TITLE"] = "Namensplaketten"
L["WN43_3_TEXT"] = "Die Gesundheitszahlen des Spiels auf unseren Plaketten stehen rechts, geteilt oder links: wähle es unter Namensplaketten in den Optionen (/fcui). Unsere Plaketten zeigen jetzt die Zahlen, die die Namensplaketten-Informationen des Spiels wählen, und der Name der Plakette unter der Maus wird gelb, wie in Classic Era."
L["WN43_4_TITLE"] = "Stufenaufstieg-Banner"
L["WN43_4_TEXT"] = "Das große Stufenaufstieg-Banner des Spiels ist jetzt ausgeblendet, 1.x hatte keins. Um es wieder zu sehen, schalte Stufenaufstieg-Banner in den Optionen (/fcui) unter Sonstiges ein."
L["WN43_5_TITLE"] = "Fenster"
L["WN43_5_TEXT"] = "Das Makrofenster und seine Symbolauswahl haben Eras Aussehen. Auf dem Charakterbogen haben die Wertekästen Eras grauen Rand, jeder Charakter behält seine eigene Auswahl der Wertebereiche, und die Unterüberschriften im Statistik-Reiter nutzen das klassische Plus und Minus. Standardoptionen schaltet jetzt auch Leisten in klassischer Größe ein; eine Chatzeile sagt, wie man es rückgängig macht."
L["WN43_6_TITLE"] = "Behoben"
L["WN43_6_TEXT"] = "Bei Ziel und Fokus mit dicken Gesundheitsleisten füllt eingehende Heilung die ganze Leiste und beginnt genau am Ende der Gesundheit. Der Filter Questlevel anzeigen der Karte wirkt nicht mehr verkehrt herum. Die Trennlinien von Leiste 1 bleiben unter der Maus ausgeblendet, die Seite eines Questgegenstands läuft nicht mehr über ihr Pergament hinaus, mit ausgeblendeten Tastenrändern verschwindet auch der Ring des Kalenders und die Lupe der Verfolgung sitzt mittig, und ausgegraute Optionen zeigen wieder ihren Tooltip."
L["WN42_1_TITLE"] = "Minikarte"
L["WN42_1_TEXT"] = "Die Minikartentasten anderer Addons und unsere Optionstaste lassen sich zeigen, beim Überfahren zeigen oder ausblenden, ohne sie zu sammeln: Addontasten, unter Minikarte in den Optionen (/fcui). Auch das Verfolgungssymbol ist ein Auswahlmenü: angezeigt, beim Überfahren oder ausgeblendet. N (Norden) ausblenden nimmt das N oben vom Rand der Minikarte; es ist standardmäßig aus, schalte es unter Minikarte in den Optionen ein. Mit dem Kalender hinter Tag und Nacht zeigt das Überfahren dieses Symbols den Kalender an seiner Stelle."
L["WN42_2_TITLE"] = "Chat"
L["WN42_2_TEXT"] = "Die Chat-Reiter und der Rahmen um das Eingabefeld lassen sich je zeigen, beim Überfahren zeigen oder ausblenden: Chat-Reiter und Rahmen des Eingabefelds, unter Chat in den Optionen (/fcui). Beim Überfahren zeigen, unter Chattasten ausblenden, holt die ausgeblendeten Tasten zurück, solange die Maus über dem Chat ist; es ist standardmäßig aus, schalte es dort in den Optionen ein."
L["WN42_3_TITLE"] = "Taschen"
L["WN42_3_TEXT"] = "Die Optionen der Taschenleiste stehen jetzt auf der Seite Taschen. Auch Schlüsselbundgrafik ausblenden, unter Grafik der Taschenleiste ausblenden, nimmt die Grafik des Schlüsselbunds mit der der Taschen weg, solange der Schlüsselbund nicht auf der Leiste ist; es ist standardmäßig aus, schalte es in den Optionen (/fcui) unter Taschen ein. Mit der Taschenleiste auf nur Rucksack und eingeklappt bleibt die Reagenzientasche, und der Schlüsselbund kommt beim Überfahren zurück. In der einen Tasche leuchten beim Überfahren einer Taschentaste wieder deren Plätze auf, die des Schlüsselbunds auch."
L["WN42_4_TITLE"] = "Einblenden beim Überfahren"
L["WN42_4_TEXT"] = "Alles, was beim Überfahren erscheint, blendet jetzt kurz ein und aus, statt plötzlich aufzutauchen und zu verschwinden."
L["WN42_5_TITLE"] = "Korrekturen"
L["WN42_5_TEXT"] = "Mit ausgeschalteten Berufsfenstern zeigt das Berufsbuch keinen dunklen Kasten mehr über seinen Rand hinaus. Eine Option auf unseren Seiten in den Spieleinstellungen legt nicht mehr den Rahmen unseres Fensters über das Fenster des Spiels, und diese Seiten reichen bis zu seinem unteren Rand; die Optionsseite behält auch ihre Scrollstelle. Menüs und Untermenüs bekommen den klassischen Look, bevor sie erscheinen. Das Sammlungsfenster behält seine Filter, und mit einem Fensterverschiebe-Addon funktioniert die volle Größe des Berufsbuchs und das Zauberbuch springt nicht mehr."
L["WN41_1_TITLE"] = "Eine Tasche"
L["WN41_1_TEXT"] = "Die Reihe der Taschenplätze in der einen Tasche bringt deren Anordnung nicht mehr mit einem Fehler durcheinander, und mit Abschnitten nach Taschenart bekommen die Plätze des Schlüsselbunds einen eigenen Abschnitt."
L["WN41_2_TITLE"] = "Zauberbuchtaste"
L["WN41_2_TEXT"] = "Taste und Knopf des Zauberbuchs öffnen wieder das Zauberbuch statt der zuletzt gezeigten Berufs- oder Sammlungsseite."
L["WN40_1_TITLE"] = "Sammlungsfenster"
L["WN40_1_TEXT"] = "Reittiere, Haustiere, Spielzeuge, Erbstücke und Vorlagen in einem klassischen Fenster mit seitlichen Reitern, mit den Modellansichten des Spiels, einem Suchfeld und einem Filter-Menü. Es öffnet sich über den Sammlungen-Knopf oder die Taste und, wenn dieser Mikroknopf ausgeblendet ist, über einen Sammlungen-Reiter am Fuß des Zauberbuchs, als Seite des Buchs. Standardmäßig an; Sammlungsfenster unter Sonstiges in den Optionen (/fcui) schaltet es aus, und Sammlungen-Reiter unter Zauberbuch blendet den Reiter aus."
L["WN40_2_TITLE"] = "Eine Leiste"
L["WN40_2_TEXT"] = "Mit Eine Leiste an nimmt Nur die Hauptleiste die Seitenpfeile und die Latenzleiste von ihr und legt den Schlüsselbund zu den Taschen. Eine Leiste einzuschalten blendet jetzt auch die Grafik von Taschen, Mikromenü und Schlüsselbund aus, rückt die Taschenknöpfe dicht zusammen und setzt das Mikromenü in die Bildschirmecke, die Taschen darauf. Eine Leiste ist standardmäßig aus; schalte sie in den Optionen (/fcui) unter Aktionsleisten ein, wo Schlüsselbund bei den Taschen und Taschen dicht beieinander auch eigene Kästchen sind."
L["WN40_3_TITLE"] = "Fenster im klassischen Stil"
L["WN40_3_TEXT"] = "Fensterrahmen heißt jetzt Fenster im klassischen Stil, auf der Seite Aussehen der Optionen: ein Schalter, darunter ein Kästchen je Fenster in einer scrollenden Liste mit Suche. Solange er aus ist, sind die Fensteroptionen der anderen Seiten ausgegraut und ihr Tooltip sagt, was einzuschalten ist. Ihn oder das Kästchen eines Fensters aus- oder einzuschalten fragt nach einem Neuladen, da ein offenes Fenster den Rahmen behält, mit dem es gebaut wurde."
L["WN40_4_TITLE"] = "Bearbeitungsmodus"
L["WN40_4_TEXT"] = "Die Totemleiste hat im Bearbeitungsmodus die Einstellungen der Haltungsleiste: Ausrichtung, Reihen, Symbolgröße und Abstand. Fokus- und Begleiterfenster können ihre Stärkungen jetzt ebenfalls oben zeigen, über ihre Dialoge im Bearbeitungsmodus, und das kleine Fokusfenster zeigt seine Schwächungen auch oben. Der Stärkungspfeil ist in den Optionen jetzt ein Aufklappmenü: angezeigt, beim Überfahren oder ausgeblendet."
L["WN40_5_TITLE"] = "Eine Tasche"
L["WN40_5_TEXT"] = "Eine Tasche kann Abschnitte nach Taschenart oder nach Tasche zeigen, die Plätze des Schlüsselbunds nach denen der letzten Tasche, in dessen Messing (der Schlüsselbund-Knopf öffnet dann die eine Tasche), und die angelegten Taschenplätze. Jedes ist ein Kästchen unter Eine Tasche in den Optionen (/fcui) unter Taschen und standardmäßig aus; schalte es dort ein."
L["WN40_6_TITLE"] = "Zauberbuchseiten und Karte"
L["WN40_6_TEXT"] = "Berufe und Sammlungen zählen als Seiten des Zauberbuchs: sein Knopf bleibt auf ihnen gedrückt, seine Taste schließt die Seite, und das Buch öffnet wieder auf der zuletzt gezeigten Seite. Die klassische Weltkarte öffnet im Fenster in der Kartenhöhe des Spiels und behält Größe und Platz durch einen Kampf."
L["WN40_7_TITLE"] = "Einheitenfenster und EP-Leiste"
L["WN40_7_TEXT"] = "Dicke Gesundheitsleisten gegnerischer Spieler zeigen deren Klassenfarbe, standardmäßig an (Auch gegnerische Spieler unter Gesundheit in Klassenfarbe). Elitefenster trennt Spieler und NSCs, sodass jedes seinen Drachen behält oder im Thema zeigt. Der Tooltip der EP-Leiste kann sagen, wie viel erholte EP übrig sind: Erholte EP im Tooltip der EP-Leiste unter Aktionsleisten, standardmäßig aus; schalte es in den Optionen (/fcui) ein."
L["WN40_8_TITLE"] = "Korrekturen"
L["WN40_8_TEXT"] = "Ein Rechtsklick auf die Kraftleiste eines Einheitenfensters öffnet wieder sein Menü, kyrillische Namen erscheinen auf Einheitenfenstern und Namensplaketten, Bedrohung in Prozent aus verbirgt auch die eigene Zahl des Spiels, eine in einem Tracker-Addon angeklickte Quest öffnet unser Questlog, und ein von seinem Addon ausgeblendeter Minikartenknopf bleibt ausgeblendet. Die volle Größe des Berufebuchs ist das klassische Buch größer gezeichnet. Ein Spielfenster, dessen klassischer Stil aus ist, bleibt dem Spiel und anderen Addons überlassen, nichts von uns darauf, und das Kästchen zum Entsperren der Karte ist dann ausgegraut. Beim Betrachten eines Spielers erscheinen immer die Reiter Charakter und PvP. Standardoptionen (vorher Optionen zurücksetzen) zählt klassisch große Leisten mit unserem Layout als Standard. Kleine Korrekturen an den Kontrollverlust-Symbolen der Namensplaketten, dem Managlühen des Druiden, dem Kasten des Spielmenüs, langen Spielmenüs und den Kästen des Bearbeitungsmodus."
L["WN39_1_TITLE"] = "Era-Kartenmarkierungen"
L["WN39_1_TEXT"] = "Auf den Karten von Kalimdor und den Östlichen Königreichen zeigen Hauptstädte wieder den grauen Turm aus Era und Orte das gelbe Haus, mit dem Namen des Orts beim Überfahren. Standardmäßig an; Era-Markierungen für Städte und Orte unter Karte in den Optionen (/fcui) schaltet es aus."
L["WN39_2_TITLE"] = "Andere Aktionsleisten-Addons"
L["WN39_2_TEXT"] = "Übernimmt ein anderes Addon die Aktionsleisten, tritt die klassische Leiste zurück, statt unter ihnen gezeichnet zu werden. Ein Fenster sagt es einmal und eine Chatzeile bei jedem Login, bis du Warnung bei übernommenen Leisten unter Addonnachrichten in den Optionen ausschaltest. Addonnachrichten schaltet jetzt auch die Willkommensnotiz stumm."
L["WN39_3_TITLE"] = "Schadensblitz"
L["WN39_3_TEXT"] = "Das Spielerfenster lässt die gerade verlorene Gesundheit nicht mehr rot aufblitzen, wie schon in 1.x. Standardmäßig aus; um ihn zurückzuholen, schalte ihn in den Optionen (/fcui) ein: Schadensblitz unter Einheitenfenster."
L["WN39_4_TITLE"] = "Fensterverschieber-Addons"
L["WN39_4_TEXT"] = "Spielfenster anderen Addons überlassen platziert, skaliert und sperrt die eigenen Fenster des Spiels nicht mehr, damit ein Fensterverschieber sie übernehmen kann; unsere behalten ihr Schloss. Standardmäßig aus; schalte es in den Optionen unter Sonstiges ein. Eine neue FAQ-Frage erklärt, warum ein Fensterverschieber manche Fenster bewegt und andere nicht."
L["WN39_5_TITLE"] = "Fehlerbehebungen"
L["WN39_5_TEXT"] = "Taschenleiste beim Überfahren zeigt die Taschen, solange die Maus irgendwo über der Reihe ist, auch zwischen zwei Taschen, und das eigene Überfahren der Reagenzientasche blendet sie abseits der klassischen Leiste nicht mehr aus. Die klassische Karte bekommt in einem Kampf sofort ihre klassische Größe und Stelle, Escape funktioniert wieder nach einem Berufsfenster, und eine Aktionsleiste ein- oder auszuschalten ordnet die klassische Leiste sofort neu."
L["WN38_1_TITLE"] = "Minikarte"
L["WN38_1_TEXT"] = "Nach dem letzten Update des Spiels zeigen der Verfolgungsknopf und die Gebietsleiste der Minikarte wieder ihr 1.x-Aussehen, und der Gebietsname hat wieder die Größe aus Era. Das Spiel zeigt dort keine Schwierigkeitsanzeige mehr, daher ist ihre Auswahl aus den Optionen verschwunden."
L["WN38_2_TITLE"] = "Fehlerbehebungen"
L["WN38_2_TEXT"] = "Angriffe lösen keinen Fehler des Schadensmessers mehr aus, der ClassicUI Forever nennt, auch wenn der Schadensmesser aus ist, und im Kampf erscheint kein Fehler über eine blockierte Aktion an der Taschenleiste mehr."
L["WN37_1_TITLE"] = "Optionen in zwei Spalten"
L["WN37_1_TEXT"] = "Die Optionen (/fcui) listen ihre Seiten links, mit der Suche, und zeigen die Seite rechts. Keine wählen und Optionen zurücksetzen gelten je Seite oder für alle, und Fenster zurücksetzen bringt jedes Fenster auf seine eigene Größe und Stelle zurück."
L["WN37_2_TITLE"] = "Taschenleiste"
L["WN37_2_TEXT"] = "Wähle Taschenleiste in den Optionen (/fcui) unter Taschenfenster: ausgeblendet, nur bis Taschen offen sind oder beim Überfahren, oder nur Rucksack, wobei ein kleiner Pfeil neben dem Rucksack, sichtbar solange die Maus darüber ist, die Taschen ausklappt."
L["WN37_3_TITLE"] = "Leiste 2 neben Leiste 1"
L["WN37_3_TEXT"] = "Wähle Leiste 2: rechts von Leiste 1 auf dem Band, oder links, in den Optionen (/fcui) unter Klassische Leiste: Leiste 2 an ihrem Standardplatz setzt die Steinfassungen des Bands neben Leiste 1 fort, mit dem Rest des Bands nach beiden."
L["WN37_4_TITLE"] = "Optionsmenü des Zauberbuchs"
L["WN37_4_TEXT"] = "Die Suchzeile des Zauberbuchs hat ein Optionsmenü: Passive ausblenden, Ähnliche Zauber in Aufklappmenüs gruppieren (sie lassen sich auch im Kampf auf die Leisten ziehen) und Alle Zauberränge anzeigen. Schalte sie dort ein, oder in den Optionen (/fcui) unter Zauberbuch."
L["WN37_5_TITLE"] = "Fehlerbehebungen"
L["WN37_5_TEXT"] = "Angriffe und Befehle eines Begleiters lassen sich im Kampf aus dem Begleiterreiter ziehen. Das Zauberbuch fliegt nach einem Kampf mit offenem Beutefenster nicht mehr weg, ein im Kampf geöffnetes Berufsfenster zeigt seine Kästen, das Ziehen der Karte mit einem Kartenaddon behält die Karte, und das Leuchten beim Überfahren eines Namensplaketts erlischt, wenn die Maus geht. Sieben neue Fragen in den FAQ."
L["WN37_6_TITLE"] = "Fenster"
L["WN37_6_TEXT"] = "Spielfenster, die ein Fensterbeweger hält, bleiben ihm überlassen. Ein Spielfenster schließt ein anderes nur, wenn beide von der Art sind, die Era schloss, die übrigen bleiben stehen, während eines aus der Reihe gezogen oder vergrößert wird, und ein Zurücksetzen stellt ein Spielfenster wieder auf seinen Platz."
L["WN36_1_TITLE"] = "Vermächtnisbäume nebeneinander"
L["WN36_1_TEXT"] = "Schalte in den Optionen (/fcui) unter Vermächtnisfenster Drei Bäume nebeneinander ein, um die drei Bäume des Vermächtnisfensters auf einmal zu sehen, mit einem Übernehmen für alle."
L["WN36_2_TITLE"] = "Minikartentasten drücken sich"
L["WN36_2_TEXT"] = "Die Minikartentasten des Addons, die Tasche der Addontasten und das Auge der Gruppensuche sinken ein, solange du die Maus darauf gedrückt hältst, wie in Era."
L["WN36_3_TITLE"] = "Fehlerbehebungen"
L["WN36_3_TEXT"] = "Kanalisierte Zauber zeigen einen grünen Zauberbalken, und der Atembalken ist wieder durchsichtig, wie in Era. Die Reiter des Charakterfensters sinken beim Klicken ein, die Questzahl im Questlog hat weiße Ziffern, und die Questüberschriften der Weltkarte bleiben golden. Die Tasche der Addontasten zeigt keine dunklen Symbole mehr, und Tasten kommen nach dem Einloggen sofort hinein."
L["WN36_4_TITLE"] = "Vermächtnistaste"
L["WN36_4_TEXT"] = "Die Vermächtnistaste bleibt nach dem Schließen ihres Fensters nicht mehr gedrückt, und das Vermächtnissymbol an der Minikarte öffnet sein Fenster wieder."
L["WN35_1_TITLE"] = "Drei Talentbäume"
L["WN35_1_TEXT"] = "Schalte in den Optionen (/fcui) unter Talentfenster Drei Bäume nebeneinander ein, um alle drei Bäume auf einmal zu sehen. Das Auswahlfeld Höhe legt fest, ob jeder Baum scrollt, das Fenster wächst oder die Reihen enger stehen."
L["WN35_2_TITLE"] = "Berufe in doppelter Ansicht"
L["WN35_2_TEXT"] = "Schalte in den Optionen (/fcui) unter Berufsfenster Doppelte Ansicht ein, für ein breiteres Fenster: die Rezepte links, das gewählte Rezept und seine Reagenzien daneben."
L["WN35_3_TITLE"] = "Reagenzientasche in der einen Tasche"
L["WN35_3_TEXT"] = "Schalte in den Optionen (/fcui) unter Taschenfenster Reagenzientasche in der einen Tasche ein, und ihre Plätze öffnen sich mit der einen Tasche wie die jeder anderen Tasche, zuerst oder zuletzt, auf Wunsch grün getönt. Fahr mit der Maus über die Reagenzientasche, um sie hervorzuheben."
L["WN35_4_TITLE"] = "Reiter des Zauberbuchs"
L["WN35_4_TEXT"] = "Die Reiter des Zauberbuchs stehen für jede Klasse in Eras Reihenfolge: bei einem Magier Arkan, Feuer, Frost."
L["WN35_5_TITLE"] = "Fehlerbehebungen"
L["WN35_5_TEXT"] = "Kombopunkte liegen wie in Era über dem PvP-Symbol des Ziels. Namensplaketten lösen in Dungeons keine Lua-Fehler mehr aus. Die Sozial-Taste öffnet bei ausgeschalteter Gildenliste wieder das Sozialfenster des Addons, und die Fenster des Addons reihen sich neben Addons ein, die die Fenster des Spiels zentrieren."
L["WN35_6_TITLE"] = "Auch auf Retail"
L["WN35_6_TEXT"] = "Die Wer-Seite zeigt die seitlichen Reiter der Gruppensuche nicht mehr, die die Gruppensuche von WoW Forever öffnen."
L["WN34_1_TITLE"] = "Fensterplatzierung"
L["WN34_1_TEXT"] = "Die Fenster des Addons öffnen sich in einer Reihe nach den Fenstern des Spiels, in der Reihenfolge, in der du sie öffnest, und richten sich nach Addons, die die Fenster des Spiels verschieben. Ein Fenster, das du verschoben hast, bleibt, wo du es hingestellt hast. Ist kein Platz mehr, schließt sich das älteste, nie im Kampf."
L["WN34_2_TITLE"] = "Zauberbuch und Talente"
L["WN34_2_TEXT"] = "Das große Zauberbuch- und Talentfenster des Spiels schließt sich, wenn du ein Fenster des Addons öffnest, das daneben keinen Platz hat, so wie das Spiel es mit seinen eigenen Fenstern macht."
L["WN34_3_TITLE"] = "Größengriff"
L["WN34_3_TEXT"] = "Solange ein Fenster entsperrt ist, ziehst du am Griff in seiner unteren rechten Ecke, um seine Größe zu ändern; ein Rechtsklick auf den Griff gibt ihm seine Standardgröße."
L["WN34_4_TITLE"] = "Auge der Gruppensuche"
L["WN34_4_TEXT"] = "Das Auge wird wieder im Bearbeitungsmodus des Spiels platziert und skaliert, mit An Minikarte ausrichten und Auch ohne Warteschlange zeigen in seinem Dialog."
L["WN34_5_TITLE"] = "Gesperrte Plätze ausblenden"
L["WN34_5_TEXT"] = "Ohne Authenticator auf deinem Account schaltest du in den Optionen (/fcui) unter Taschenfenster Gesperrte Plätze ausblenden ein, und der Rucksack schrumpft auf die Plätze, die du nutzen kannst."
L["WN34_6_TITLE"] = "Karte und Werte"
L["WN34_6_TEXT"] = "Maximiert behält die Weltkarte ihr Era-Aussehen, auf den Bildschirm skaliert. Der Tooltip für Schaden zeigt für jede Hand Angriffstempo und Schaden pro Sekunde, wie in Era."
L["WN34_7_TITLE"] = "Auch auf Forever"
L["WN34_7_TEXT"] = "Die klassische Weltkarte zeigt deine Koordinaten und die des Mauszeigers in einer Zeile in ihrer Fußleiste. Der Begleiter-Reiter zeigt Eras Zeilen Angriff, Angriffskraft, Schaden, Verteidigung und Rüstung."
L["WN33_1_TITLE"] = "Freundschaftsanfragen"
L["WN33_1_TEXT"] = "Die Reiter der Freundesseite sind Freunde, Kürzliche Verbündete und Freundschaftsanfragen. Battle.net-Freundschaftsanfragen warten auf ihrem eigenen Reiter, ihre Anzahl im Namen: eine auswählen und Annehmen oder Ablehnen. Die Ignorierliste steht im Dropdown neben deinem Battle.net-Namen."
L["WN33_2_TITLE"] = "Communitys als Taste"
L["WN33_2_TEXT"] = "Standardmäßig aus: Schalte Communitys als Taste in den Optionen (/fcui) unter Gildenliste ein. Communitys verlässt dann die Reiterleiste für eine runde Taste auf der Gildenseite, und die vier Reiter behalten ihre 1.x-Breite. Ohne Gilde steht ein Communitys-Reiter an der Stelle des Gildenreiters."
L["WN33_3_TITLE"] = "Update-Hinweis"
L["WN33_3_TEXT"] = "Hat jemand in deiner Gilde oder Gruppe eine neuere Version von ClassicUI Forever, sagt dir eine Zeile im Chat Bescheid, mit einem Link zu CurseForge. Addonnachrichten unter Sonstiges in den Optionen schaltet sie mit den übrigen Chatzeilen des Addons ab."
L["WN33_4_TITLE"] = "Flüssigere Haltungswechsel"
L["WN33_4_TEXT"] = "Verstohlenheit des Schurken, Druidengestalten und andere Haltungswechsel verursachen kein kurzes Ruckeln mehr, und die Questverfolgung springt dabei nicht mehr."
L["WN33_5_TITLE"] = "PvP-Details"
L["WN33_5_TEXT"] = "Die Detailleiste des PvP-Reiters ist wie die des Spiels aufgebaut, in 1.x-Teilen: eine Linie unter deinem Rang, die Überschrift der nächsten Belohnungen in einem eisernen Rahmen und das Symbol der Belohnung in einem Gegenstandsplatz."
L["WN33_6_TITLE"] = "Begleiter-Reiter"
L["WN33_6_TEXT"] = "Der Begleiter-Reiter zeigt die Trainingspunkte deines Begleiters, und seine EP-Leiste zeigt ihre Zahlen immer, wie in Era. Wird der Begleiter bei offener Charakterseite beschworen, erscheint er nicht mehr an deiner Stelle."
L["WN33_7_TITLE"] = "Korrekturen"
L["WN33_7_TEXT"] = "Haltungs-, Begleiter- und Besessenheitstasten folgen dem Thema. Die Reiterleisten von Kontakte- und Charakterfenster passen auch in langen Sprachen wie Deutsch, ohne abgeschnittene Beschriftung. Rufzeilen leuchten unter der Maus wie in Era, und das Beutefenster öffnet sich hinter deinen offenen Fenstern. Die Chatzeilen des Addons beginnen mit seinem Greifen."
L["WN32_1_TITLE"] = "Eras Weltkarte"
L["WN32_1_TEXT"] = "Die Weltkarte zeigt standardmäßig Eras großen Kartenrahmen, mit Auswahllisten für Kontinent und Zone und Herauszoomen in der Kopfleiste. Jeder Stil zeigt die Karte in seiner eigenen Größe; die Größe änderst du jederzeit in ClassicUI Forever Fenster (Bearbeitungsmodus). Für die kleine Karte wie bisher wähle Navigationsleiste: keine in den Optionen (/fcui) unter Weltkarte."
L["WN32_2_TITLE"] = "Kartenoptionen"
L["WN32_2_TEXT"] = "Ein Feld Kartenoptionen unten rechts auf der klassischen Weltkarte wählt, was die Karte zeigt. Ob es immer, beim Darüberfahren oder nie erscheint, wählst du in den Optionen unter Weltkarte."
L["WN32_3_TITLE"] = "Eras Zauberleiste auf Namensplaketten"
L["WN32_3_TEXT"] = "Die Zauberleisten der Namensplaketten sehen aus wie in Era, mit dem Zaubersymbol im linken Feld der Leiste. Die Plakette deines Ziels und die unter der Maus leuchten heller, und ein nicht unterbrechbarer Zauber behält sein Symbol unter Eras Schild. Für die alte Zauberleiste aktiviere Zauberleiste: Symbol daneben in den Optionen unter Namensplaketten."
L["WN32_4_TITLE"] = "Freie Taschenplätze"
L["WN32_4_TEXT"] = "Die Zahl der freien Plätze im Rucksack folgt der Spieleinstellung für freien Taschenplatz unter Interface in den Spieloptionen, wie in Era: aus, bis du sie aktivierst, und nie doppelt angezeigt."
L["WN32_5_TITLE"] = "Korrekturen"
L["WN32_5_TEXT"] = "Tastenrahmen ausblenden erfasst auch die Tag-und-Nacht- und Zoomtasten der Minikarte und hinterlässt beim Ausschalten keinen zusätzlichen Ring. In ClassicUI Forever Fenster (Bearbeitungsmodus) erscheinen die Rahmen geschlossener Fenster dort, wo die Fenster sitzen, und Position zurücksetzen bringt die Weltkarte an die Stelle des Spiels zurück. Akzeptieren im Talentfenster passt auf seine Taste. Neue Installationen öffnen das Questlog in der doppelten Ansicht."
L["WN31_1_TITLE"] = "Das Handwerksfenster aus Era"
L["WN31_1_TEXT"] = "Das Handwerksfenster hat die Größe, Grafik und Anordnung aus Era, mit einem Filter nach der Art des hergestellten Gegenstands und Rezeptdetails, die rollen, wenn die Reagenzien nicht mehr hineinpassen."
L["WN31_2_TITLE"] = "Berufebuch"
L["WN31_2_TEXT"] = "Das Berufebuch liegt auf dem Pergament des Zauberbuchs, mit dem Wappen jedes Berufs. Die Reiter neben dem Berufsfenster erscheinen beim Darüberfahren; immer sichtbar oder verborgen wählst du in den Optionen (/fcui) unter Berufebuch. Für die Seite mit den Bändern schalte dort Buch im Cataclysm-Stil ein."
L["WN31_3_TITLE"] = "Taschen und Schlüsselbund"
L["WN31_3_TEXT"] = "Die Taschen auf der Leiste folgen Ausrichtung und Richtung aus dem Bearbeitungsmodus, Vertikal stellt sie also in eine Spalte. Auch der Schlüsselbund kann auf der Seite liegen: setze Horizontal in seinem Bearbeitungsmodus-Dialog."
L["WN31_4_TITLE"] = "Mehr vom Aussehen aus Era"
L["WN31_4_TEXT"] = "Bücher und Briefe öffnen sich im Lesefenster aus Era, jede Minikarten-Schaltfläche trägt den Steinring aus Era, und Textfelder in Popups sowie die Kontakte-Schaltfläche des Kontaktfensters haben die Formen aus Era."
L["WN31_5_TITLE"] = "Designfarben"
L["WN31_5_TEXT"] = "Mit einem eigenen Design nimmt mehr Grafik seine Farbe an, etwa die Listen- und Bildlaufränder in den meisten Fenstern, die kleine Weltkarte und der Tag-und-Nacht-Ring der Minikarte."
L["WN31_6_TITLE"] = "Optionen"
L["WN31_6_TEXT"] = "Ein Regler Max. Kameraentfernung in den Optionen (/fcui) unter Sonstiges lässt die Kamera bis 4,0 zurückfahren. Nur Treffer zeigen bei der Optionssuche listet nur die passenden Optionen."
L["WN31_7_TITLE"] = "Korrekturen"
L["WN31_7_TEXT"] = "Plündern schließt deine offenen Fenster nicht mehr, Taschen auf der Leiste zeigen keinen silbernen Rand mehr, und eine Neuinstallation auf dem klassischen Layout bringt nicht mehr die Leisten in Spielgröße zurück. Ein gekürzter Name in der Wer-Liste erscheint vollständig, wenn du darauf zeigst, und Trainieren wird für einen neuen Beruf ausgegraut, wenn beide Berufsplätze belegt sind, wie in Era. Berufsleisten zeigen nicht mehr zwei Grüntöne, und der Freunde-Knopf am Chat öffnet nicht mehr das Sozialfenster des Spiels."
L["WN31_8_TITLE"] = "Außerdem auf Forever"
L["WN31_8_TEXT"] = "Das Charakterfenster hat den Munitionsplatz aus Era mit seinem Pfeil zum Distanzplatz, und das Gruppensuchefenster zeigt das Auge aus Era, das sich dreht, solange du gelistet bist. Das im Kampf vom Reiter Berufe geöffnete Zauberbuch öffnet sich nicht mehr seitlich versetzt, die Grafik des Vermächtnisfensters verrutscht zwischen seinen Seiten nicht mehr, und die Symbole des Berufebuchs springen während einer Herstellung nicht mehr umher. Die Leisten im Reiter Fertigkeiten haben Größe und Abstand aus Era, mit Eras goldenem Rand unter dem Mauszeiger."
L["WN31_9_TITLE"] = "Gruppensuche-Auge und Verfolgungssymbol"
L["WN31_9_TEXT"] = "Das Gruppensuche-Symbol und das Warteschlangenauge des Spiels sind eine Taste: In der Warteschlange nimmt das Auge den Platz des Symbols im Aussehen aus Era ein und dreht sich wie dort. Das Verfolgungssymbol hat den größeren Ring aus Era; für die alte Größe schalte in den Optionen (/fcui) unter Minikarte Verfolgungssymbol: so groß wie die anderen Tasten ein."
L["WN31_10_TITLE"] = "Andere Addons an der Minikarte"
L["WN31_10_TEXT"] = "Addons, die Minikarten-Tasten in einer Tasche sammeln, lassen das Gruppensuche-Auge und die anderen Minikarten-Symbole am Ring, und die Optionstaste zeigt in ihrer Tasche ihren Greifen. Der eckige Minikartenrand eines anderen Addons erscheint nicht mehr um die runde Minikarte."
L["WN30_1_TITLE"] = "Korrekturen an den Aktionsleisten"
L["WN30_1_TEXT"] = "Zwischen den Tasten der Hauptleiste blitzen beim Seitenwechsel, etwa mit Verstohlenheit oder Druidengestalten, keine goldenen Trennlinien mehr auf, und der goldene Rand einer eingeschalteten Fähigkeit ist wieder vollständig."
L["WN30_2_TITLE"] = "Lehrer"
L["WN30_2_TEXT"] = "Trainieren im klassischen Lehrerfenster lernt die gewählte Fertigkeit oder das Rezept wieder, und dein Geld darunter wird in voller Helligkeit gezeigt."
L["WN29_1_TITLE"] = "Ein klassisches Vermächtnisfenster"
L["WN29_1_TEXT"] = "Die Vermächtnis-Schaltfläche und -Taste öffnen ein klassisches Vermächtnisfenster: die Belohnungsleiste und die Herausforderungen auf alten Fertigkeitsbalken, mit Suche und Filter, und die Vermächtnisbäume im alten Talentfenster. Standardmäßig an; abschalten in den Optionen (/fcui) unter Charakter und Zauber."
L["WN29_2_TITLE"] = "Deine eigenen Layouts bleiben deine"
L["WN29_2_TEXT"] = "Mit abgeschaltetem Addon stehen die Aktionsleisten in deinen eigenen Bearbeitungsmodus-Layouts nicht mehr an den Stellen der klassischen Leiste. Dort früher gespeicherte Stellen werden beim nächsten Druck auf UI neu laden in den Optionen (/fcui) oder mit /fcui off zurückgegeben."
L["WN29_3_TITLE"] = "Korrekturen"
L["WN29_3_TEXT"] = "/fcui off schaltet das Addon wieder aus. Ein Klick auf ein Gildenmitglied im Kampf öffnet seine Details. Das Einstellungsfenster des Spiels zeigt nach einem Kampf keine Fehlerflut mehr, Questlevel bleiben mit abgeschalteter Option verborgen, und der Pfeil nach unten im Chat blinkt nicht mehr auf."
L["WN29_4_TITLE"] = "Waffenplätze"
L["WN29_4_TEXT"] = "Die Waffenplätze im Charakterfenster stehen mittig auf zwei Mulden, ohne die leere Mulde für den Fernkampfplatz."
L["WN28_1_TITLE"] = "Kürzliche Verbündete und Ignorieren"
L["WN28_1_TEXT"] = "Der Freunde-Reiter des Kontaktfensters hat neben Freunde die Reiter Kürzliche Verbündete und Ignorieren. Kürzliche Verbündete zeigt die Spieler, mit denen du zuletzt in einer Gruppe warst, mit einer Suchzeile; Ignorieren zeigt die Spieler, die du ignorierst."
L["WN28_2_TITLE"] = "Wieder das klassische Kontaktfenster"
L["WN28_2_TEXT"] = "Seit dem letzten Spielupdate öffneten O und der Gildenknopf das neue Kontaktfenster des Spiels. Sie öffnen wieder das klassische, seine Reiter sitzen richtig, und der Schlachtzugsreiter ist zurück."
L["WN28_3_TITLE"] = "Korrekturen nach dem Spielupdate"
L["WN28_3_TEXT"] = "Die Combopunkte zeigen wieder alle fünf klassischen Kugeln. Der dunkle Streifen über dem Charaktermodell und der dunkle Kasten auf den Eintragsseiten der Gruppensuche sind weg, der Sortierknopf funktioniert im Ein-Taschen-Modus, und die Gruppensuche springt nicht mehr, wenn sie im Kampf geöffnet wird."
L["WN28_4_TITLE"] = "Beutefenster und Taschen"
L["WN28_4_TEXT"] = "Mit ausgeschaltetem Beutefenster zeigt das Beutefenster des Spiels keine zwei weißen Quadrate mehr in seinen Ecken. Der Sortierknopf der Taschen passt neben das Suchfeld."
L["WN27_1_TITLE"] = "Weniger Hintergrundarbeit"
L["WN27_1_TEXT"] = "Die Namensplaketten werden nur noch neu angeordnet, wenn sich eine Namensplaketten-Einstellung ändert, nicht mehr bei jeder Einstellung, die das Spiel oder ein anderes Addon ändert. Die Koordinaten der Minikarte werden nur noch gemessen, wenn sie sich ändern. Am Aussehen ändert sich nichts."
L["WN26_1_TITLE"] ="Klassenfarben je Fenster"
L["WN26_1_TEXT"] = "Gesundheit in Klassenfarbe und Namensfeld in Klassenfarbe sind standardmäßig aus; schalte sie in den Optionen (/fcui) unter Einheitenfenster ein. Beide haben jetzt darunter eine Auswahl der Fenster: Spieler, Ziel und Fokus, so kann das Ziel seine Klassenfarbe tragen, während dein eigenes Fenster bleibt, wie es war."
L["WN26_2_TITLE"] = "Namensfeldfarbe"
L["WN26_2_TEXT"] = "Eine neue Auswahl Namensfeldfarbe unter Einheitenfenster bestimmt, bei welchen Fenstern das Namensfeld die Farbe des Spiels für die Einheit annimmt (Blau für einen freundlichen Spieler). Ziel und Fokus sind angehakt, wie in Classic Era; ohne Haken bleibt das Feld schlicht. Spieler ist standardmäßig aus; schalte es in den Optionen (/fcui) ein, um dein eigenes zu färben."
L["WN26_3_TITLE"] = "Korrekturen"
L["WN26_3_TEXT"] = "Mit der dicken Gesundheitsleiste über dem Namen ist das Namensfeld des Spielerfensters nicht mehr hinter der Leiste zu sehen. Wird das Namensfeld in Klassenfarbe abgewählt, verschwindet die Farbe bei Ziel und Fokus sofort."
L["WN25_1_TITLE"] = "Greifen"
L["WN25_1_TEXT"] = "Die Greifen werden jetzt mit dem Layout des Bearbeitungsmodus gespeichert, wie die eigenen Elemente des Spiels: Jedes Layout behält seine eigenen Plätze für sie, und Speichern auf einer Spielvorlage fragt nach einem neuen Layout, das sie übernimmt. Eine nicht gespeicherte Verschiebung wird beim Schließen des Bearbeitungsmodus verworfen. Das klassische Layout in den Optionen setzt sie wieder an die Enden der Leiste."
L["WN24_1_TITLE"] = "Taschen"
L["WN24_1_TEXT"] = "Offene Taschen springen nicht mehr zur Seite, wenn du einen Gegenstand per Rechtsklick anlegst, im Kampf wie außerhalb."
L["WN23_1_TITLE"] = "Schlagtimer"
L["WN23_1_TEXT"] = "Ein Waffenwechsel im Kampf löst keinen Lua-Fehler mehr in jedem Bild aus, in dem die Schlagleiste zu sehen ist, und das Aufblitzen beim Schlag funktioniert nach dem Wechsel weiter."
L["WN22_1_TITLE"] = "Berufe"
L["WN22_1_TEXT"] = "Ein Beruf öffnet sich im klassischen Berufsfenster, und das Berufebuch ist das alte kleine im Rahmen des Zauberbuchs. Die Größentaste neben der Schließen-Taste wechselt jeweils zum vollen Fenster des Spiels."
L["WN22_2_TITLE"] = "Zauberbuch und Talente"
L["WN22_2_TEXT"] = "Eine Zauberbuch-Taste im Mikromenü, neben Charakter, öffnet das klassische Zauberbuch. Das Talentfenster des Spiels trägt den klassischen Rahmen, und die Talente-Taste öffnet es immer bei deinen Talenten."
L["WN22_3_TITLE"] = "Mikromenü und Minikarte"
L["WN22_3_TEXT"] = "Erfolge, Abenteuerführer und Behausung sind nicht mehr im Mikromenü, da 1.x keine hatte, und jede hat ein Symbol an der Minikarte. Um eine Taste zurückzuholen, entferne ihren Haken unter Mikrotasten ausblenden in den Optionen (/fcui)."
L["WN22_4_TITLE"] = "Schnellbeitritt"
L["WN22_4_TEXT"] = "Schnellbeitritt hat die Reiterleiste des Kontaktfensters verlassen. Öffne Freunde, dann Kürzliche Verbündete: Der Reiter Schnellbeitritt unter der Liste wechselt dorthin, der Reiter Kürzliche Verbündete zurück."
L["WN22_5_TITLE"] = "Leistung"
L["WN22_5_TEXT"] = "Farbthemen brauchen deutlich weniger CPU: Die gefärbten Grafiken folgen denen des Spiels nur noch, wenn sich etwas ändert, nicht in jedem Bild. Rechtsklickmenüs an Porträts, Taschen und Fenster öffnen sich ohne Ruckeln."
L["WN22_6_TITLE"] = "Makros"
L["WN22_6_TEXT"] = "Ein Zauber, der mit Umschalt-Klick aus dem klassischen Zauberbuch in ein Makro gesetzt wird, steht dort mit Name und Rang, wie aus dem Buch des Spiels; bisher war es ein Chatlink, den ein Makro nicht wirken kann. Das Makrofenster hat die Reiter von Classic Era."
L["WN22_7_TITLE"] = "Makros"
L["WN22_7_TEXT"] = "Ein Zauber, der mit Umschalt-Klick aus dem klassischen Zauberbuch in ein Makro gesetzt wird, steht dort mit Name und Rang, wie aus dem Buch des Spiels; bisher war es ein Chatlink, den ein Makro nicht wirken kann. Talente stehen ebenfalls mit ihrem Namen dort. Das Makrofenster hat die Reiter von Classic Era."
L["WN22_8_TITLE"] = "Dropdown-Menüs"
L["WN22_8_TEXT"] = "Die Dropdown-Menüs des Spiels, etwa das Statusmenü (Verfügbar, Abwesend, Beschäftigt) und das Aufspürmenü der Minikarte, haben jetzt den Eisenrahmen von Classic Era, und er umschließt ihre Symbole und Pfeile."
L["WN22_9_TITLE"] = "Ruf und Währungen"
L["WN22_9_TEXT"] = "Beide Reiter behalten die klassischen Zeilen: gleichmäßige Abstände, die alten Überschriften, eine Spalte von Balken. Eine Gruppe von Fraktionen hat ihre Plus- oder Minus-Taste, ihre Fraktionen stehen eingerückt darunter, und der Filter ist eine kleine Pfeiltaste oben rechts."
L["WN22_10_TITLE"] = "Weitere Korrekturen"
L["WN22_10_TEXT"] = "Die Reiter unter einem Fenster bleiben auf seinem unteren Rand; bei manchen Interfacegrößen wanderten sie nach oben. Ein Umschalt-Klick auf einen Beruf lässt das Zauberbuch offen, die Manazahlen eines Druiden in Gestalten folgen der Einstellung Statustext des Spiels, und der Reiter Hilfe zeigt nur die Fragen zu der Spielversion, die du spielst."
L["WN22_11_TITLE"] = "Fenster in Retail"
L["WN22_11_TEXT"] = "Die Reagenzientasche steht frei von der Latenzleiste, das Charakterfenster hat keine dünnen Linien um das Modell, das Kontaktfenster hat nur einen Wer-Reiter, und die Fensterränder sitzen wie in Forever."
L["WN21_1_TITLE"] = "Gildenliste"
L["WN21_1_TEXT"] = "Ein Klick auf ein Mitglied öffnet jetzt bei jedem Mitglied dessen Notizen und Optionen; in größeren Gilden öffnete sich bei vielen nichts. Die Liste braucht außerdem deutlich weniger CPU, solange sie offen ist."
L["WN21_2_TITLE"] = "Quests teilen"
L["WN21_2_TEXT"] = "Quest teilen im klassischen Questlog funktioniert mit einem Klick für jede Quest, auch direkt nach dem Einloggen. Bisher ging es nur bei Quests des Gebiets, das die Weltkarte zuletzt zeigte."
L["WN21_3_TITLE"] = "Fenster"
L["WN21_3_TEXT"] = "Ein geöffneter Brief hat den klassischen Fensterrahmen wie der Posteingang, und die Seitenleiste des Charakterfensters zeigt bei manchen Interfacegrößen keine dünne durchsichtige Linie mehr."
L["WN20_1_TITLE"] ="PvP-Rangdetails"
L["WN20_1_TEXT"] = "Der PvP-Reiter des Charakterfensters kann deine Rangdetails und die Belohnungen des nächsten Rangs zeigen. Klicke auf den Pfeil unten rechts im Reiter, um die Seitenleiste zu öffnen."
L["WN20_2_TITLE"] = "Addon-Tasche"
L["WN20_2_TEXT"] = "Ihr Standardplatz liegt jetzt links neben der Uhr, frei vom Auge der Gruppensuche, und sie lässt unsere eigenen Minikartensymbole wie Vermächtnis auf der Minikarte. Die Schaltfläche Klassisches Layout stellt auch verschobene Minikartenknöpfe zurück."
L["WN20_3_TITLE"] = "Andere Addons"
L["WN20_3_TEXT"] = "Teile von ClassicUI Forever, die du ausschaltest, lassen die Fenster des Spiels jetzt in Ruhe, sodass Addons, die sie umgestalten, ihr Aussehen behalten."
L["WN19_1_TITLE"] = "Minikartensymbole"
L["WN19_1_TEXT"] = "Jede Mikrotaste kann jetzt als Symbol an der Minikarte sitzen: Hake sie in den Optionen (/fcui) unter Mikrotasten an der Minikarte an. Vermächtnis und die Gruppensuche sind standardmäßig an, so ist Vermächtnis wieder erreichbar. Mit gedrückter Umschalttaste ziehst du unsere Minikartentasten um den Ring."
L["WN19_2_TITLE"] = "Questverfolgung"
L["WN19_2_TEXT"] = "Die Zielverfolgung kann die schlichte Questverfolgung aus Classic Era sein. Standardmäßig aus; zum Einschalten stelle in den Optionen (/fcui) unter Quests die Zielverfolgung auf Verfolgung aus Classic Era. Klick auf einen Titel öffnet die Quest, Umschalt-Klick beendet die Verfolgung, Rechtsklick zeigt mehr."
L["WN19_3_TITLE"] = "Optionsfenster"
L["WN19_3_TEXT"] = "Das Optionsfenster ist größer, und seine langen Listen sind jetzt Dropdowns, so gibt es weniger zu scrollen."
L["WN19_4_TITLE"] = "Bedrohung in Prozent"
L["WN19_4_TEXT"] = "Die Bedrohung in Prozent kann nur in Gruppe oder Dungeon erscheinen: Schalte in den Optionen (/fcui) unter Einheitenfenster Nur in Gruppe oder Dungeon ein. Standardmäßig aus."
L["WN19_5_TITLE"] = "Details aus Classic Era"
L["WN19_5_TEXT"] = "Der Tooltip der Spielmenütaste hat die Beschreibungen aus Classic Era, Dropdown-Menüs haben den Eisenrahmen aus Classic Era, und Mikrotasten werden bei geöffnetem Spielmenü nicht mehr grau."
L["WN19_6_TITLE"] = "Fehlerbehebungen"
L["WN19_6_TEXT"] = "Optionen zurücksetzen behält die klassisch großen Leisten, eigene Designs färben die Reiter der Optionen ganz, die Grafik der klassischen Leiste bleibt im Layout ClassicUI Forever sichtbar, die Optionstaste überdeckt die Verfolgungslupe nicht mehr, und ist Minikarte abgewählt, bleiben von einem anderen Addon ausgeblendete Minikartensymbole ausgeblendet."
L["WN18_1_TITLE"] = "Berufe"
L["WN18_1_TEXT"] = "Im Berufsfenster kannst du jetzt ein Rezept verfolgen (seine Reagenzien stehen in der Zielverfolgung), nach Ausrüstungsplatz filtern und deinen Beruf mit dem Kettenglied neben dem Titel im Chat verlinken. Die Berufetaste öffnet wieder das Berufsbuch."
L["WN18_2_TITLE"] = "Elitedrachen"
L["WN18_2_TEXT"] = "Elitegegner können auf der Namensplakette einen goldenen Drachen um ihre Stufe zeigen, seltene einen silbernen: Schalte in den Optionen (/fcui) unter Namensplaketten Elitedrachen ein. Mit einem eigenen Design halten Design für Elitefenster ignorieren und Design für Plakettendrachen ignorieren unter Eigenes Design die Drachen golden und silbern. Alles standardmäßig aus."
L["WN18_3_TITLE"] = "Kampfleuchten"
L["WN18_3_TEXT"] = "Um das rote Pulsieren des Spielerfensters beim Angreifen abzustellen, schalte in den Optionen (/fcui) unter Einheitenfenster Kampfleuchten ausblenden ein. Standardmäßig aus."
L["WN18_4_TITLE"] = "Zauberleisten"
L["WN18_4_TEXT"] = "Unterbrochene Zauber bei Ziel, Fokus und Namensplaketten werden jetzt rot und zeigen nur Unterbrochen, wie in Classic Era. Um zu sehen, wer unterbrochen hat, schalte in den Optionen (/fcui) unter Zauberleisten Unterbrecher nennen ein. Kanalisierte Zauber erscheinen grün."
L["WN18_5_TITLE"] = "Instanzschwierigkeit"
L["WN18_5_TEXT"] = "Die Schwierigkeitsflagge, die das Spiel in Dungeons und Schlachtzügen an der Minikarte zeigt, ist jetzt ausgeblendet. Um sie zurückzuholen, wähle in den Optionen (/fcui) unter Minikarte angezeigt oder beim Überfahren."
L["WN18_6_TITLE"] = "Klassisches Layout"
L["WN18_6_TEXT"] = "Die Haltbarkeitsfigur versteckt sich nicht mehr hinter den seitlichen Leisten, und Stärkungszauber sitzen an den Stellen aus Classic Era neben der Minikarte. Das Layout bietet außerdem die Interfacegröße aus Classic Era an, wenn deine abweicht."
L["WN18_7_TITLE"] = "Aussehen"
L["WN18_7_TEXT"] = "Menüs haben den schwarzen Hintergrund aus Classic Era, und Namensplaketten haben die Größe aus Classic Era. Der leere Teil der EP- und Rufleisten ist wie in Classic Era abgedunkelt; um das abzuschalten, entferne unter Klassische Leiste das Häkchen bei Abgedunkelte EP- und Rufleisten."
L["WN18_8_TITLE"] = "Fehlerbehebungen"
L["WN18_8_TEXT"] = "Erlernen funktioniert auch für Rezepte weit unten in der Liste eines Lehrers. Die Chatknöpfe bleiben auf jedem Chatreiter, und Umschalt-Klick verlinkt ein Talent im Chat. Die im Kampf geöffnete Weltkarte fängt keine Klicks mehr ab, und die roten Knöpfe des Bearbeitungsmodus bleiben beim Designwechsel ganz."
L["WN17_1_TITLE"] = "Fehler bei Namensplaketten"
L["WN17_1_TEXT"] = "Mit einem Design lösen die klassischen Namensplaketten keine Fehlermeldungen mehr aus."
L["WN17_2_TITLE"] = "Stärkungszauber des Ziels"
L["WN17_2_TEXT"] = "Stärkungszauber unter dem Ziel- und Fokusfenster erscheinen beim Zielwechsel jetzt gleich an ihrem Platz, ohne kurzes Springen."
L["WN17_3_TITLE"] = "Weltkarte im Kampf"
L["WN17_3_TEXT"] = "Die klassische Weltkarte sieht im Kampf geöffnet jetzt genauso aus wie außerhalb des Kampfes."
L["WN16_1_TITLE"] = "Aktionssymbole"
L["WN16_1_TEXT"] = "Mit einem Design werden die Symbole der Aktionstasten nicht mehr zufällig dunkel."
L["WN16_2_TITLE"] = "Kampfleuchten"
L["WN16_2_TEXT"] = "Mit Dicke Gesundheitsleisten über dem Namen leuchten das rote Kampfleuchten und das goldene Ausruhleuchten jetzt um das ganze Spielerfenster statt über der Gesundheitsleiste. Dicke Gesundheitsleisten sind standardmäßig aus; schalte sie in den Optionen (/fcui) unter Einheitenfenster ein."
L["WN16_3_TITLE"] = "Namensplaketten"
L["WN16_3_TEXT"] = "Mit ausgeschalteten klassischen Namensplaketten lösen die Namensplaketten des Spiels keine Fehlermeldungen mehr aus."
L["WN15_1_TITLE"] = "Bedrohung"
L["WN15_1_TEXT"] = "Die Bedrohung in Prozent aus Classic Era steht jetzt im Kampf über dem Ziel- und Fokusfenster. Das rote Leuchten um die Einheitenfenster ist jetzt standardmäßig aus; um es zurückzuholen, entferne in den Optionen (/fcui) unter Einheitenfenster das Häkchen bei Bedrohungsleuchten ausblenden."
L["WN15_2_TITLE"] = "Druidenmana"
L["WN15_2_TEXT"] = "In Bären- und Katzengestalt sehen Druiden ihr Mana jetzt in einer kleinen Leiste unter der Wut- oder Energieleiste."
L["WN15_3_TITLE"] = "Farbe der Gegner"
L["WN15_3_TEXT"] = "Standardmäßig aus. Schalte dazu in den Optionen (/fcui) unter Einheitenfenster Dicke Gesundheitsleisten ein und wähle unter Gesundheit von Gegnern Nach Gesinnung: Neutrale Gegner bekommen eine gelbe Leiste, feindliche eine rote."
L["WN15_4_TITLE"] = "Englischer Text"
L["WN15_4_TEXT"] = "Für ein Spiel in einer anderen Sprache: Die eigenen Texte dieses Addons können Teil für Teil auf Englisch erscheinen. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Sonstiges, Englischer Text, ein."
L["WN15_5_TITLE"] = "Wer-Liste"
L["WN15_5_TEXT"] = "Der Pfeil oben in der letzten Spalte der Wer-Liste enthält jetzt die Klassen-, Volks- und Zonenfilter des Spiels. Eine Suche mit ein oder zwei Treffern bleibt im Fenster, statt im Chat zu landen."
L["WN15_6_TITLE"] = "Einfarbig"
L["WN15_6_TEXT"] = "Einfarbig malt die Grafik von Fenstern und Leisten in einer festen Farbe statt in Metall. Es behält jetzt die feinen Linien in Fenstern, um Listen, Fußleisten und Trenner, außer du schaltest auch Innere Ränder ausblenden ein. Beides ist standardmäßig aus: Schalte in den Optionen (/fcui) unter Aussehen erst Eigenes Design, dann Einfarbig ein."
L["WN15_7_TITLE"] = "Schlagtimer"
L["WN15_7_TEXT"] = "Die Schlagtimer können jetzt ohne das Aufblitzen nach jedem Schlag laufen: Entferne in den Optionen (/fcui) unter Schlagtimer das Häkchen bei Aufblitzen beim Schlag."
L["WN15_8_TITLE"] = "Namensplaketten"
L["WN15_8_TEXT"] = "Namen und kleine Zahlen auf Namensplaketten nutzen jetzt die schlichte Schrift aus Classic Era. Neu und standardmäßig aus: Gleiche Größe nah und fern hält jede Namensplakette gleich groß, wie in Classic Era; schalte es in den Optionen (/fcui) unter Namensplaketten ein."
L["WN15_9_TITLE"] = "Fenster"
L["WN15_9_TEXT"] = "Quest-, Gesprächs- und Händlerfenster und die Liste im Questlog haben jetzt den dünnen Rand aus Classic Era um ihren Inhalt, und das Charakterfenster zeigt auf jedem Reiter das Gesicht deines Charakters."
L["WN15_10_TITLE"] = "Korrekturen"
L["WN15_10_TEXT"] = "Mit einem Design nehmen Symbolränder, Porträtringe, Menüs und die Seitenpfeile beim Händler seine Farbe an, und Schieberegler bleiben sichtbar. Die Reiter des Charakterfensters reagieren jetzt dort, wo sie gezeichnet sind."
L["WN14_1_TITLE"] = "Controller"
L["WN14_1_TEXT"] = "Mit der Gamepad-Oberfläche öffnen sich das klassische Zauberbuch, die Talente und das Questlog in den eigenen Fenstern des Spiels, sodass ein Controller sich darin bewegen kann."
L["WN14_2_TITLE"] = "Design überall"
L["WN14_2_TEXT"] = "Mit einem Design nehmen auch die eigenen Teile des Spiels seine Farbe an, wo die klassischen aus sind: Minikarte, Einheitenfenster, Leisten, Fenster und die Tasten des Spielmenüs."
L["WN14_3_TITLE"] = "Dunkelheit"
L["WN14_3_TEXT"] = "Dunkel hat einen Schieberegler von Hellgrau bis Schwarz, mit einer Taste zurück zum Standard."
L["WN14_4_TITLE"] = "Einfarbig"
L["WN14_4_TEXT"] = "Einfarbig (Eigenes Design) zeigt die angehakten Teile in einer flachen Farbe, in denselben Formen."
L["WN14_5_TITLE"] = "Mikrotasten"
L["WN14_5_TEXT"] = "Mikrotasten ausblenden wirkt jetzt auch auf das eigene Mikromenü des Spiels bei ausgeschalteter klassischer Leiste und kann den Shop ausblenden."
L["WN14_6_TITLE"] = "Leisten 6 bis 8"
L["WN14_6_TEXT"] = "Leisten 6 bis 8 ausblenden ist entfallen: Die Aktionsleisten-Einstellungen des Spiels entscheiden."
L["WN14_7_TITLE"] = "Korrekturen"
L["WN14_7_TEXT"] = "Koordinaten: ausgeblendet und beim Überfahren wirken mit der Minikarte des Spiels, Minikartentasten anderer Addons nehmen das Design an, und der Rucksack eines Jägers zeigt freie Taschenplätze statt Munition."
L["WN13_1_TITLE"] = "Bedrohungsleuchten"
L["WN13_1_TEXT"] = "Bedrohungsleuchten ausblenden (Einheitenfenster) nimmt das rote Bedrohungsleuchten von den Einheitenfenstern. Die Bedrohungszahl des Spiels bleibt."
L["WN13_2_TITLE"] = "Questgegenstände"
L["WN13_2_TEXT"] = "Schlichte Questgegenstände (Taschenfenster) zeigt Questgegenstände in Taschen und Bank ohne Questrahmen."
L["WN13_3_TITLE"] = "Zahlen"
L["WN13_3_TEXT"] = "Zahlen ohne Trennzeichen (Einheitenfenster) entfernt die Tausendertrennzeichen aus großen Zahlen, auf den Leisten und im ganzen Spiel."
L["WN13_4_TITLE"] = "Aktionssymbole"
L["WN13_4_TEXT"] = "Mit einem Design zeigen sich Aktionssymbole wieder ganz, wie in Classic Era; nur ihr eigener Rand nimmt die Farbe des Designs an."
L["WN13_5_TITLE"] = "Deine Leisten"
L["WN13_5_TEXT"] = "Hat 0.14.0 deine Leisten verändert, kannst du sie über eine Chatzeile beim Einloggen wiederherstellen oder den klassischen Look wählen."
L["WN13_6_TITLE"] = "Sozialfenster"
L["WN13_6_TEXT"] = "Die Reiter Freunde und Schlachtzug stehen wie in Classic Era in ihrem dünnen Rahmen, und die Beschreibung des Schlachtzugreiters erscheint außerhalb eines Schlachtzugs wieder."
L["WN13_7_TITLE"] = "Korrekturen"
L["WN13_7_TEXT"] = "Beute an der Maus öffnet mit dem ersten Gegenstand unter dem Zeiger, Reiterbeschriftungen werden beim Darüberfahren weiß, und Klassisches Layout bringt das klassische Mikromenü und die Taschenplätze zurück."
L["WN12_1_TITLE"] = "Fenster"
L["WN12_1_TEXT"] = "Neben dem Schließen-Knopf jedes Fensters sitzen ein Schloss und ein Zurücksetzen: Ein entsperrtes Fenster zieht man an seinem Titel. Quest- und Gesprächsfenster, Sozialfenster, Gruppensuche und Berufebuch lassen sich in ClassicUI Forever Fenster platzieren und skalieren."
L["WN12_2_TITLE"] = "Schlagtimer"
L["WN12_2_TEXT"] = "Die Schlagtimer des Spiels im Stil der 1.x-Zauberleiste, mit einer Farbe pro Hand und einem Aufblitzen bei jedem Schlag. Farben und Rahmenstärke stellt man in den Optionen ein."
L["WN12_3_TITLE"] = "Dicke Gesundheitsleisten"
L["WN12_3_TEXT"] = "Eine höhere Gesundheitsleiste auf dem Spieler-, Ziel- und Fokusfenster, über dem Namen oder über dem Mana (Einheitenfenster). Dort sind auch Namensfeld in Klassenfarbe und Namensgröße neu."
L["WN12_4_TITLE"] = "Greifen"
L["WN12_4_TEXT"] = "Die Greifen lassen sich im Bearbeitungsmodus des Spiels ziehen, skalieren oder ausblenden. Mit eingeschaltetem Einrasten richten sie sich an den Leisten aus und kehren an ihren Platz zurück."
L["WN12_5_TITLE"] = "Schadensmesser"
L["WN12_5_TEXT"] = "Der Schadensmesser im 1.x-Rahmen mit klassischen Knöpfen und einem Marmor- oder Talentbaum-Hintergrund, den man verschieben kann."
L["WN12_6_TITLE"] = "Sprachen"
L["WN12_6_TEXT"] = "ClassicUI Forever gibt es jetzt auf Deutsch, Französisch, Spanisch und Italienisch."
L["WN12_7_TITLE"] = "Optionen"
L["WN12_7_TEXT"] = "Neue Reiter FAQ und Support, eine Eigene Farbe für das Thema und eine Suche, die eine Einstellung unter mehr Namen findet."
L["WN12_8_TITLE"] = "Ressourcenanzeige"
L["WN12_8_TEXT"] = "Die persönliche Ressourcenanzeige in 1.x-Leisten und im alten Namensplakettenrahmen, mit der Einstellung Leistenabstand."
L["WN12_9_TITLE"] = "Klassische Leiste"
L["WN12_9_TEXT"] = "Taschenplätze in klassischer Größe, jede Mikrotaste lässt sich ausblenden, die Hilfe-Taste steht wieder am Ende des Mikromenüs, und Band trägt Leisten 2 und 3 hält diese Leisten auf dem Band."
L["WN12_10_TITLE"] = "Minikarte und Chat"
L["WN12_10_TEXT"] = "Koordinaten sowie ein ausblendbarer Rand und Kopf an der Minikarte, das Auge der Gruppensuche daran, wenn ihre Mikrotaste ausgeblendet ist, und jede Chattaste lässt sich einzeln ausblenden."
L["WN12_11_TITLE"] = "Korrekturen"
L["WN12_11_TEXT"] = "Leisten springen nach dem Ziehen im Bearbeitungsmodus nicht mehr an den oberen Bildschirmrand, Leiste 1 bewegt sich im Bearbeitungsmodus mit den Pfeiltasten, die EP-Leiste erscheint nach dem Einloggen im Kampf nicht mehr doppelt, und Beuteseiten wiederholen keine Gegenstände mehr."
L["WN12_12_TITLE"] = "Kleinere Korrekturen"
L["WN12_12_TEXT"] = "Begleiter- und Gruppenzahlen passen in ihre Leisten, das Mikromenü springt beim Ziehen nicht mehr, die Latenzleiste behält ihren Rahmen, und die Tipps der Mikrotasten erscheinen einmal und mit der richtigen Questgrenze."
L["WN11_1_TITLE"] = "Chat"
L["WN11_1_TEXT"] = "Chattasten ausblenden lässt den Chat am Bildschirmrand sitzen, und Chat-Bildlaufleiste behält die Bildlaufleiste von WoW Forever (Chattasten)."
L["WN11_2_TITLE"] = "Queststufen"
L["WN11_2_TEXT"] = "Queststufen (Quests) zeigt die Stufe jeder Quest auf der Karte, in der Questverfolgung und im Questlog, im Einklang mit dem eigenen Filter der Karte."
L["WN11_3_TITLE"] = "Dunkles Design"
L["WN11_3_TEXT"] = "Rechtsklickmenüs, Minikartentasten von Addons, die Zoomtasten, Uhr und das Tag-und-Nacht-Symbol übernehmen das Design, und Aktionssymbole zeigen keinen hellen Rand."
L["WN11_4_TITLE"] = "Korrekturen"
L["WN11_4_TEXT"] = "Keine doppelte Queststufe in der Questverfolgung, keine Fehler durch Rechtsklickmenüs in Dungeons, und das Menü des Ziels bleibt auf dem Bildschirm."
L["WN10_1_TITLE"] = "Minikarte"
L["WN10_1_TEXT"] = "Jedes Teil der Minikarte kann erscheinen, nur beim Überfahren erscheinen oder ausgeblendet sein (Minikarte in den Optionen), und Hinein- und Herauszoomen bewegen sich in ClassicUI Forever Fenster einzeln um den Ring."
L["WN10_2_TITLE"] = "Mikromenü"
L["WN10_2_TEXT"] = "Die Beschreibungen von Classic Era in den Tooltips der Mikrotasten, und Mikrotasten ausblenden nimmt einzelne Tasten aus dem Menü (Klassische Leiste)."
L["WN10_3_TITLE"] = "Schlüsselbund"
L["WN10_3_TEXT"] = "Öffnet sich auch ohne Schlüssel, in einem eigenen Fenster, in der Grafik von Classic Era."
L["WN10_4_TITLE"] = "Neue Optionen"
L["WN10_4_TEXT"] = "Haltungsleiste ausblenden (Klassische Leiste), Größe des Namenstexts (Namensplaketten) und Einheiten-Tooltip auf Leisten (Einheitenfenster)."
L["WN10_5_TITLE"] = "Korrekturen"
L["WN10_5_TEXT"] = "Bildlaufpfeile werden grau, wenn nichts zu scrollen ist, das Questlog hebt wie in Classic Era hervor, Zuletzt online in der Gilde sortiert richtig und das Makrofenster öffnet sich neben dem Zauberbuch."
L["WN10_6_TITLE"] = "Kleinere Korrekturen"
L["WN10_6_TEXT"] = "Talentpfeile, der Gildenreiter ohne Gilde, Seitenpfeile über der Karte, die Tasche für Addontasten und kürzere Layoutabfragen."
L["WN9_1_TITLE"] = "Klassische Weltkarte"
L["WN9_1_TEXT"] = "Die kleine Karte von Classic Era, mit der Questliste der Karte in einem eigenen Bereich daneben und Belohnungen nach dem Questtext. Kartennavigationsleiste unter Karte in den Optionen bringt das Kartenlayout des Spiels zurück."
L["WN9_2_TITLE"] = "Neue Optionen"
L["WN9_2_TEXT"] = "Questtaste der Karte ausblenden (Karte), Leisten in klassischer Größe (Klassische Leiste) und Wackeln bei Unterbrechung (Zauberleisten)."
L["WN9_3_TITLE"] = "Klassischer Look"
L["WN9_3_TEXT"] = "Rechtsklickmenüs, Auswahllisten, das Kontaktefenster, die Gruppensuche, die Wer-Liste und die Gildenliste folgen Classic Era; das Einstellungsfenster übernimmt den Look des heutigen Classic-Era-Clients, und Ignorierliste und Anprobe den klassischen Look."
L["WN9_4_TITLE"] = "Bearbeitungsmodus"
L["WN9_4_TEXT"] = "Das Zauberbuch lässt sich in ClassicUI Forever Fenster verschieben und in der Größe ändern."
L["WN9_5_TITLE"] = "Leisten und Questverfolgung"
L["WN9_5_TEXT"] = "Die Leisten 4 und 5 behalten ihren Platz am Bildschirmrand, und die Questverfolgung liegt nicht mehr über ihnen."
L["WN9_6_TITLE"] = "Korrekturen"
L["WN9_6_TEXT"] = "Neutrale NSCs zeigen ihre Stufe statt eines Totenkopfs, und ein Klick auf die Leisten eines Einheitenfensters wählt wieder ein Ziel."
L["WN9_7_TITLE"] = "Fenster und Reiter"
L["WN9_7_TEXT"] = "Händler-, Post-, Gildenurkunden- und Wappenrockfenster sowie viele andere Fenster und Reiter richten sich nach Classic Era aus; Escape schließt das Gildenurkundenfenster."
L["WN8_1_TITLE"] = "Greifen über den Leisten"
L["WN8_1_TEXT"] = "Aktiviere Greifen über den Leisten unter Klassische Leiste in den Optionen, um die Greifen vor die Leisten 2 und 3 zu zeichnen."
L["WN8_2_TITLE"] = "Fenster öffnen beim Tastendruck"
L["WN8_2_TEXT"] = "Die Tasten für Zauberbuch, Berufe, Talente, Gilde und Questlog sowie Escape reagieren beim Drücken, wie die eigenen Fenster des Spiels."
L["WN8_3_TITLE"] = "Korrekturen"
L["WN8_3_TEXT"] = "Zauber lassen sich wieder auf Aktionsleiste 1 ziehen, der Gebietsname ist auf der Minikartenleiste zentriert, wo immer der Kalender sitzt, und die Reiter und Begleiterbefehle des Zauberbuchs sehen richtig aus."
L["WN7_1_TITLE"] = "Klassischer Tastentext"
L["WN7_1_TEXT"] = "Tastennamen auf den Aktionstasten haben die Größe und Umrandung von Classic Era. Größe des Tastentexts unter Tastenstil in den Optionen macht sie größer oder kleiner."
L["WN7_2_TITLE"] = "Kalenderplätze"
L["WN7_2_TEXT"] = "Der Kalender ist ein kleines Quadrat beim Gebietsnamen; setz ihn auf den Ring oder hinter das Tag-und-Nacht-Symbol unter Kalendertaste in den Optionen. Markiere Kalender unter Minikarte in ClassicUI Forever Fenster im Bearbeitungsmodus, um ihn zu verschieben oder in der Größe zu ändern."
L["WN6_1_TITLE"] = "Kalendertaste"
L["WN6_1_TEXT"] = "Der Kalender sitzt unter dem Tag-und-Nacht-Symbol an der Minikarte. Um ihn auszublenden, entferne das Häkchen bei Kalendertaste unter Minikarte in den Optionen."
L["WN5_1_TITLE"] = "Korrekturen"
L["WN5_1_TEXT"] = "Die Markierung für neue Spieler in der Gruppensuche richtet sich an den Rollensymbolen aus. Details im vollständigen Änderungsprotokoll."
L["WN4_1_TITLE"] = "Korrekturen"
L["WN4_1_TEXT"] = "Reiter nehmen die Maus am Reiter selbst an, ein aus dem Zauberbuch gewirkter Beruf schließt das Buch im Kampf, und der Kopf des Beutefensters ist sauber. Details im vollständigen Änderungsprotokoll."
L["WN3_1_TITLE"] = "Teile der klassischen Leiste"
L["WN3_1_TEXT"] = "Classic hatte keine Berufetaste und keine Reagenzientasche, daher ist die Berufetaste aus dem Mikromenü (Berufe öffnen sich aus dem Zauberbuch) und die Reagenzientasche ist eine kleine runde Taste beim Überfahren. Die Leisten 2 und 3 passen wieder zwischen die Greifen. Beides sind Zeilen unter Klassische Leiste in den Optionen."
L["WN2_1_TITLE"] = "Fenster-Bearbeitungsmodus"
L["WN2_1_TEXT"] = "Markiere Fenster im Bearbeitungsmodus, um Charakterfenster, Zauberbuch, Talente, Questlog, Berufe und Karte zu verschieben und in der Größe zu ändern."
L["WN2_2_TITLE"] = "Profile"
L["WN2_2_TEXT"] = "Ein Reiter Profile in den Optionen speichert benannte Einstellungen pro Charakter."
L["WN2_3_TITLE"] = "Bronze oder Dunkel"
L["WN2_3_TEXT"] = "Das eigene Design gibt es in der Bronze von Forever oder in dunklem Anthrazit. Siehe die Option Eigenes Design."
L["WN2_4_TITLE"] = "Klassische Leiste"
L["WN2_4_TEXT"] = "Die Leisten werden standardmäßig nicht mehr verkleinert. Die Leiste trägt jetzt Latenzleiste, Schlüsselbund und Reagenzientasche wie in Classic; jedes davon lässt sich im Bearbeitungsmodus verschieben oder unter Klassische Leiste in den Optionen ausblenden."
L["WN2_5_TITLE"] = "Minikartentasten"
L["WN2_5_TEXT"] = "Die Minikartentasten anderer Addons können sich hinter einer Taste am Ring sammeln. Siehe die Option Addontasten sammeln."
L["WN2_6_TITLE"] = "Optionen"
L["WN2_6_TEXT"] = "Abschnitte für Quests und Karte sowie neue Zeilen für den Kartenrahmen, das Beutefenster, Beutewürfe, das Ausblenden der Zielverfolgung des Spiels, die Berufetaste und den Tastentext."
L["WN2_7_TITLE"] = "Klassisches Layout zurücksetzen"
L["WN2_7_TEXT"] = "Setzt Fenster, Questverfolgung, Greifen, Leistenteile und Layouteinstellungen auf einmal zurück."
